// Some portions generated by Codex
package org.eclipse.rdf4j.workbench.commands;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Stream;

import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.explanation.Explanation;
import org.eclipse.rdf4j.query.explanation.GenericPlanNode;
import org.eclipse.rdf4j.query.explanation.TelemetryMetricNames;

import tools.jackson.databind.ObjectMapper;

/** Shared admission checks for real Workbench producers, using executed public explanation metrics. */
final class WorkbenchNativeQueryAssertions {

	private static final ObjectMapper JSON = new ObjectMapper();

	private WorkbenchNativeQueryAssertions() {
	}

	static Map<BindingSet, Long> bag(List<BindingSet> rows) {
		Map<BindingSet, Long> bag = new LinkedHashMap<>();
		rows.forEach(row -> bag.merge(row, 1L, Long::sum));
		return bag;
	}

	static void writeEvidence(Path directory, String id, String query, Map<String, ?> metadata,
			Explanation explanation) throws IOException {
		Files.createDirectories(directory);
		Files.writeString(directory.resolve(id + ".rq"), query);
		Files.writeString(directory.resolve(id + ".executed.json"), explanation.toJson());
		Files.writeString(directory.resolve(id + ".metadata.json"), JSON.writeValueAsString(metadata));
		Files.writeString(directory.resolve(id + ".executed.txt"), explanation.toString());
	}

	static void assertEfficientExecutedPlan(Explanation explanation, String label) {
		assertEfficientExecutedPlan(explanation, label, false);
	}

	static void assertEfficientExecutedPlan(Explanation explanation, String label, boolean simpleBoundedLookup) {
		List<String> witnessed = new ArrayList<>();
		List<String> nativeWork = new ArrayList<>();
		List<String> missing = new ArrayList<>();
		inspect(explanation.toGenericPlanNode(), false, witnessed, nativeWork, missing);
		assertThat(missing).as("%s: generic scans need witnessed bound index lookups\n%s", label, explanation)
				.isEmpty();
		assertThat(witnessed).as("%s: require executed native work or bound indexed generic work\n%s", label,
				explanation).isNotEmpty();
		if (!simpleBoundedLookup) {
			assertThat(nativeWork).as("%s: a composed generated query requires executed native operator work\n%s",
					label, explanation).isNotEmpty();
		}
	}

	private static void inspect(GenericPlanNode node, boolean nativeParent, List<String> witnessed,
			List<String> nativeWork, List<String> missing) {
		String path = node.getStringMetricActual(TelemetryMetricNames.NATIVE_EXECUTION_PATH);
		boolean nativeHere = path != null && Stream.of(path.split(" \\| ")).anyMatch(route -> {
			String strategy = route.contains("(") ? route.substring(0, route.indexOf('(')) : route;
			return !strategy.isBlank() && !strategy.equals("...") && !strategy.equals("genericFallback")
					&& !strategy.equals("nativeEntryBindingVariant");
		});
		if (nativeHere) {
			witnessed.add(node.getType() + ": " + path);
			nativeWork.add(node.getType() + ": " + path);
		}
		List<GenericPlanNode> children = node.getPlans() == null ? List.of() : node.getPlans();
		boolean statement = node.getType().startsWith("StatementPattern");
		boolean pathNode = node.getType().startsWith("ArbitraryLengthPath");
		Long lookups = node.getLongMetricActual(TelemetryMetricNames.INDEX_LOOKUP_COUNT_ACTUAL);
		if (statement && lookups != null && lookups > 0) {
			String index = node.getStringMetricActual(TelemetryMetricNames.INDEX_NAME);
			if (index == null) {
				index = node.getStringMetricActual(TelemetryMetricNames.INDEX_NAMES);
			}
			boolean restricted = boundIndexPrefix(index, children);
			if (index != null && !index.isBlank() && restricted) {
				witnessed.add(node.getType() + ": " + index + " (" + lookups + " bound lookups)");
			} else {
				missing.add(node.getType() + ": index=" + index + ", lookups=" + lookups
						+ ", restricted=" + restricted);
			}
		} else if ((statement || pathNode) && !nativeParent && !nativeHere
				&& node.getResultSizeActual() != null && node.getResultSizeActual() > 0) {
			missing.add(node.getType() + ": produced rows without native or actual bound-index evidence");
		}
		if (node.getType().startsWith("EmptySet")) {
			witnessed.add("optimizer-proven empty set");
			nativeWork.add("optimizer-proven empty set");
		}
		if (!pathNode) {
			// The child of an arbitrary path is an evaluator template, rebound for each traversed endpoint.
			children.forEach(child -> inspect(child, nativeParent || nativeHere, witnessed, nativeWork, missing));
		}
	}

	private static boolean boundIndexPrefix(String indexNames, List<GenericPlanNode> variables) {
		if (indexNames == null) {
			return false;
		}
		List<String> indexes = Stream.of(indexNames.split("[^a-z]+"))
				.filter(index -> index.matches("[spoc]{4}"))
				.toList();
		return !indexes.isEmpty() && indexes.stream().allMatch(index -> {
			int position = "spoc".indexOf(index.charAt(0));
			return position < variables.size() && restricted(variables.get(position));
		});
	}

	private static boolean restricted(GenericPlanNode variable) {
		return variable.getType().contains(", value=")
				|| "bound".equals(variable.getStringMetricActual(TelemetryMetricNames.BINDING_STATE));
	}
}
